-- Run inside private_read.sql's disposable transaction AFTER its assertions.
-- The bus below is the existing synthetic adapter, not the hosted M26 chain.
-- The exact staged rejection helper and wrapper are generated by the harness.
ALTER FUNCTION public.iberfit_execute_command_v26(jsonb) SET SCHEMA private;
ALTER FUNCTION private.iberfit_execute_command_v26(jsonb) RENAME TO gx_document_bus_internal_v1;
REVOKE ALL ON FUNCTION private.gx_document_bus_internal_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;
\ir bus_boundary_generated.sql
REVOKE ALL ON FUNCTION public.iberfit_execute_command_v26(jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.iberfit_execute_command_v26(jsonb) TO authenticated,service_role;
SELECT gx_test.assert(NOT has_function_privilege('authenticated','private.gx_document_bus_internal_v1(jsonb)','EXECUTE') AND NOT has_function_privilege('service_role','private.gx_document_bus_internal_v1(jsonb)','EXECUTE'),'internal bus not callable by API roles');
SELECT gx_test.actor('10000000-0000-4000-8000-000000000002');
-- Existing marked report cannot be updated or replayed via the generic entry.
SET ROLE authenticated;
SELECT gx_test.assert(public.iberfit_execute_command_v26(jsonb_build_object('type','INFORME_APROBAR','entityType','report','entityId',report_id,'clientId',client_id,'operationId',gen_random_uuid(),'baseRevision',3,'payload',jsonb_build_object('patch',jsonb_build_object('evidence',jsonb_build_array(jsonb_build_object('source',E' \tCONNECTED360:forged'))))))->>'reason'='GX_DOCUMENT_AUTHORIZED_TRANSITION_REQUIRED','forged input denied') FROM gx_test.scenarios;
SELECT gx_test.assert(public.iberfit_execute_command_v26(jsonb_build_object('type','INFORME_PUBLICAR','entityType','report','entityId',report_id,'clientId',client_id,'operationId',gen_random_uuid(),'baseRevision',3,'payload','{}'::jsonb))->>'reason'='GX_DOCUMENT_AUTHORIZED_TRANSITION_REQUIRED','direct publication denied') FROM gx_test.scenarios;
SELECT gx_test.expect_error('SELECT private.gx_document_bus_internal_v1(''{}''::jsonb)','42501','direct internal call denied');
RESET ROLE;
SELECT gx_test.assert(public.iberfit_execute_command_v26(jsonb_build_object('type',r.command_type,'entityType','report','entityId',r.entity_id,'clientId',r.client_id,'operationId',r.operation_id,'baseRevision',r.base_revision,'payload','{}'::jsonb))->>'reason'='GX_DOCUMENT_AUTHORIZED_TRANSITION_REQUIRED','existing receipt cannot bypass guard') FROM public.command_receipts_v26 r;
SELECT gx_test.assert(private.gx_document_generic_rejection_v1(jsonb_build_object('type','INFORME_RETIRAR','entityType','report','entityId',report_id,'clientId',client_id,'payload',jsonb_build_object('patch','{"status":"retirado","withdrawnAt":"2026-11-28T10:00:00.000Z","visibleToClient":false,"reason":"Synthetic withdrawal"}'::jsonb))) IS NULL,'ordinary UI withdrawal metadata allowed') FROM gx_test.scenarios;
SELECT gx_test.assert(private.gx_document_generic_rejection_v1(jsonb_build_object('type','INFORME_RETIRAR','entityType','report','entityId',report_id,'clientId',client_id,'payload',jsonb_build_object('patch','{"evidence":[]}'::jsonb)))='GX_DOCUMENT_AUTHORIZED_TRANSITION_REQUIRED','withdrawal cannot erase evidence') FROM gx_test.scenarios;
SELECT gx_test.assert(private.gx_document_generic_rejection_v1(jsonb_build_object('type','INFORME_RETIRAR','entityType','report','entityId',report_id,'clientId',client_id,'payload',jsonb_build_object('patch','{"visibleToClient":true}'::jsonb)))='GX_DOCUMENT_AUTHORIZED_TRANSITION_REQUIRED','withdrawal cannot expose document') FROM gx_test.scenarios;
SELECT gx_test.assert(private.gx_document_generic_rejection_v1('{"type":"SESION_PUBLICAR","entityType":"session"}'::jsonb) IS NULL,'nonreport untouched');
-- Ordinary report approval still delegates to the synthetic bus unchanged.
INSERT INTO public.domain_entities_v26(entity_type,entity_id,client_id,status,revision,body)
 SELECT 'report',id,client_id,status::text,revision,content FROM public.reports WHERE id='70000000-0000-4000-8000-000000000003';
SET ROLE authenticated;
SELECT gx_test.assert(public.iberfit_execute_command_v26(jsonb_build_object('type','INFORME_APROBAR','entityType','report','entityId','70000000-0000-4000-8000-000000000003','clientId','30000000-0000-4000-8000-000000000001','operationId',gen_random_uuid(),'baseRevision',1,'payload','{}'::jsonb))->>'kind'='ack','ordinary report delegates');
RESET ROLE;
SELECT gx_test.assert((SELECT status::text FROM public.reports WHERE id='70000000-0000-4000-8000-000000000003')='aprobado','ordinary projection persisted');
\echo GX_DOCUMENT_BUS_BOUNDARY_PG17_OK
